-- PT102-S2-Q7. Batch 08.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT102-S2-Q7$batch08$ AND q.stimulus=$batch08$Generations of European-history students have been taught that a political assassination caused the First World War. Without some qualification, however, this teaching is bound to mislead, since the war would not have happened without the treaties and alliances that were already in effect and the military force that was already amassed. These were the deeper causes of the war, whereas the assassination was a cause only in a trivial sense. It was like the individual spark that happens to ignite a conflagration that was, in the prevailing conditions, inevitable.$batch08$ AND q.prompt=$batch08$Which one of the following most accurately restates the main point of the passage?$batch08$ AND q.correct_choice=$batch08$C$batch08$) THEN RAISE EXCEPTION 'Question changed: PT102-S2-Q7'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch08$PT102-S2-Q7$batch08$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT102-S2-Q7'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT102-S2-Q7$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Conclusion$batch08$, $batch08$Without qualification, the teaching that the assassination caused the war misleads: the assassination was a cause only in a trivial sense, and the treaties, alliances, and amassed forces were the deeper causes.$batch08$), (1, $batch08$Evidence$batch08$, $batch08$The war wouldn't have happened without those treaties, alliances, and forces. The assassination was like a spark igniting a fire that was already inevitable.$batch08$), (2, $batch08$Evaluate$batch08$, $batch08$Note what the author does *not* say. The author doesn't deny that the assassination was a cause. It was the spark. The point is that "cause" applies more deeply to the conditions.$batch08$), (3, $batch08$Goal$batch08$, $batch08$The assassination was a cause, but the deeper causes were the conditions.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT102-S2-Q7$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$This is the most popular wrong answer. The author does call the assassination a cause, "only in a trivial sense". And the author doesn't give every event an equal claim: the conditions are called the *deeper* causes.$batch08$), ($batch08$B$batch08$, $batch08$The author says war was inevitable "in the prevailing conditions", not that all of history was fixed.$batch08$), ($batch08$C$batch08$, $batch08$The assassination counts as a cause, but "cause" applies more fundamentally to the conditions. That is the qualification the author wants added.$batch08$), ($batch08$D$batch08$, $batch08$This is a hypothetical the author never discusses.$batch08$), ($batch08$E$batch08$, $batch08$How the war would have gone with a different trigger isn't the author's point.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT102-S2-Q7$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
